SELECT id, user_id, username, role_codes, action, object_type, object_id, result,
       before_value, after_value, ip_address, trace_id, created_at
FROM audit_log

    username LIKE CONCAT('%',#{username},'%')
    AND action=#{action}

ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM audit_log

    username LIKE CONCAT('%',#{username},'%')
    AND action=#{action}
